{
  "actions": [
    {
      "title": "Create Comment",
      "description": "Creates a new comment on an issue.",
      "type": "action",
      "documentation": "https://linear.app/developers/graphql",
      "endpointUrl": "https://api.linear.app/graphql",
      "apiBaseUrl": "https://api.linear.app",
      "method": "POST",
      "sampleResponse": {
        "data": {
          "comment": {
            "id": "comment_123",
            "body": "This is a sample comment",
            "issueId": "issue_456"
          }
        }
      },
      "inputSchema": {
        "type": "object",
        "description": "Input for creating a comment",
        "properties": {
          "issueId": {
            "type": "string",
            "description": "The ID of the issue to which the comment belongs"
          },
          "body": {
            "type": "string",
            "description": "The content of the comment"
          }
        },
        "required": [
          "issueId",
          "body"
        ]
      },
      "outputType": {
        "outputType": "object"
      }
    },
    {
      "title": "Create Issue",
      "description": "Creates a new issue.",
      "type": "action",
      "documentation": "https://linear.app/developers/graphql",
      "endpointUrl": "https://api.linear.app/graphql",
      "apiBaseUrl": "https://api.linear.app",
      "method": "POST",
      "sampleResponse": {
        "data": {
          "issue": {
            "id": "issue_789",
            "title": "New Issue",
            "description": "Description of the issue"
          }
        }
      },
      "inputSchema": {
        "type": "object",
        "description": "Input for creating an issue",
        "properties": {
          "title": {
            "type": "string",
            "description": "The title of the issue"
          },
          "description": {
            "type": "string",
            "description": "A detailed description of the issue"
          },
          "teamId": {
            "type": "string",
            "description": "The ID of the team under which the issue is created"
          }
        },
        "required": [
          "title",
          "teamId"
        ]
      },
      "outputType": {
        "outputType": "object"
      }
    },
    {
      "title": "Delete Comment",
      "description": "Deletes an existing comment by its ID.",
      "type": "action",
      "documentation": "https://linear.app/developers/graphql",
      "endpointUrl": "https://api.linear.app/graphql",
      "apiBaseUrl": "https://api.linear.app",
      "method": "POST",
      "sampleResponse": {
        "data": {
          "deleteComment": {
            "success": true
          }
        }
      },
      "inputSchema": {
        "type": "object",
        "description": "Input for deleting a comment",
        "properties": {
          "commentId": {
            "type": "string",
            "description": "The ID of the comment to delete"
          }
        },
        "required": [
          "commentId"
        ]
      },
      "outputType": {
        "outputType": "object"
      }
    },
    {
      "title": "Delete Issue",
      "description": "Deletes an existing issue by its ID.",
      "type": "action",
      "documentation": "https://linear.app/developers/graphql",
      "endpointUrl": "https://api.linear.app/graphql",
      "apiBaseUrl": "https://api.linear.app",
      "method": "POST",
      "sampleResponse": {
        "data": {
          "deleteIssue": {
            "success": true
          }
        }
      },
      "inputSchema": {
        "type": "object",
        "description": "Input for deleting an issue",
        "properties": {
          "issueId": {
            "type": "string",
            "description": "The ID of the issue to delete"
          }
        },
        "required": [
          "issueId"
        ]
      },
      "outputType": {
        "outputType": "object"
      }
    },
    {
      "title": "Execute GraphQL Query",
      "description": "Performs an arbitrary authorized GraphQL query. Use with caution.",
      "type": "action",
      "documentation": "https://linear.app/developers/graphql",
      "endpointUrl": "https://api.linear.app/graphql",
      "apiBaseUrl": "https://api.linear.app",
      "method": "POST",
      "sampleResponse": {
        "data": {}
      },
      "inputSchema": {
        "type": "object",
        "description": "Input for executing a raw GraphQL query",
        "properties": {
          "query": {
            "type": "string",
            "description": "The GraphQL query string"
          },
          "variables": {
            "type": "object",
            "description": "Optional variables for the GraphQL query"
          }
        },
        "required": [
          "query"
        ]
      },
      "outputType": {
        "outputType": "object"
      }
    },
    {
      "title": "Get Comment",
      "description": "Retrieves details of a specific comment by its ID.",
      "type": "action",
      "documentation": "https://linear.app/developers/graphql",
      "endpointUrl": "https://api.linear.app/graphql",
      "apiBaseUrl": "https://api.linear.app",
      "method": "POST",
      "sampleResponse": {
        "data": {
          "comment": {
            "id": "comment_123",
            "body": "This is a comment",
            "issueId": "issue_456"
          }
        }
      },
      "inputSchema": {
        "type": "object",
        "description": "Input for retrieving a comment",
        "properties": {
          "commentId": {
            "type": "string",
            "description": "The ID of the comment to retrieve"
          }
        },
        "required": [
          "commentId"
        ]
      },
      "outputType": {
        "outputType": "object"
      }
    },
    {
      "title": "Get Issue",
      "description": "Retrieves details of a specific issue by its ID.",
      "type": "action",
      "documentation": "https://linear.app/developers/graphql",
      "endpointUrl": "https://api.linear.app/graphql",
      "apiBaseUrl": "https://api.linear.app",
      "method": "POST",
      "sampleResponse": {
        "data": {
          "issue": {
            "id": "issue_789",
            "title": "Issue Title",
            "description": "Issue description"
          }
        }
      },
      "inputSchema": {
        "type": "object",
        "description": "Input for retrieving an issue",
        "properties": {
          "issueId": {
            "type": "string",
            "description": "The ID of the issue to retrieve"
          }
        },
        "required": [
          "issueId"
        ]
      },
      "outputType": {
        "outputType": "object"
      }
    },
    {
      "title": "Update Comment",
      "description": "Updates an existing comment with new content.",
      "type": "action",
      "documentation": "https://linear.app/developers/graphql",
      "endpointUrl": "https://api.linear.app/graphql",
      "apiBaseUrl": "https://api.linear.app",
      "method": "POST",
      "sampleResponse": {
        "data": {
          "updateComment": {
            "id": "comment_123",
            "body": "Updated comment content"
          }
        }
      },
      "inputSchema": {
        "type": "object",
        "description": "Input for updating a comment",
        "properties": {
          "commentId": {
            "type": "string",
            "description": "The ID of the comment to update"
          },
          "body": {
            "type": "string",
            "description": "The new content for the comment"
          }
        },
        "required": [
          "commentId",
          "body"
        ]
      },
      "outputType": {
        "outputType": "object"
      }
    },
    {
      "title": "Find Comments",
      "description": "Retrieves a list of comments with an optional search query.",
      "type": "action",
      "documentation": "https://linear.app/developers/graphql",
      "endpointUrl": "https://api.linear.app/graphql",
      "apiBaseUrl": "https://api.linear.app",
      "method": "POST",
      "sampleResponse": {
        "data": {
          "comments": [
            {
              "id": "comment_123",
              "body": "First comment"
            },
            {
              "id": "comment_124",
              "body": "Second comment"
            }
          ]
        }
      },
      "inputSchema": {
        "type": "object",
        "description": "Input for finding comments",
        "properties": {
          "query": {
            "type": "string",
            "description": "Search term to filter comments"
          }
        }
      },
      "outputType": {
        "outputType": "array",
        "arrayPropertyLabel": "Comments",
        "arrayPropertyValue": "comments"
      }
    },
    {
      "title": "Find Issues",
      "description": "Retrieves a list of issues with an optional search query.",
      "type": "action",
      "documentation": "https://linear.app/developers/graphql",
      "endpointUrl": "https://api.linear.app/graphql",
      "apiBaseUrl": "https://api.linear.app",
      "method": "POST",
      "sampleResponse": {
        "data": {
          "issues": [
            {
              "id": "issue_789",
              "title": "Issue One"
            },
            {
              "id": "issue_790",
              "title": "Issue Two"
            }
          ]
        }
      },
      "inputSchema": {
        "type": "object",
        "description": "Input for finding issues",
        "properties": {
          "query": {
            "type": "string",
            "description": "Search term to filter issues"
          }
        }
      },
      "outputType": {
        "outputType": "array",
        "arrayPropertyLabel": "Issues",
        "arrayPropertyValue": "issues"
      }
    }
  ],
  "authentication": {
    "type": "oauth2",
    "authUrl": "https://linear.app/oauth/authorize",
    "tokenUrl": "https://linear.app/oauth/token",
    "profileInfoUrl": "https://api.linear.app/me"
  },
  "serviceJson": {
    "name": "appmixer.linear",
    "label": "Linear",
    "category": "applications",
    "description": "Integration component for Linear’s GraphQL API providing core operations like creating, retrieving, updating, and deleting issues and comments.",
    "version": "1.0.0",
    "icon": "https://linear.app/favicon.svg"
  }
}
